-- =============================================================================
-- Migration 0072: Examentraining — inhoud aanvullen tot 8 vragen per soort
-- =============================================================================
-- Gegenereerd door scripts/examen-inhoud-aanvullen-8.ts — niet met de hand bewerken.
--
-- Vier clusters over de inhoud van een omwentelingslichaam hadden vier vragen.
-- Deze migratie vult elk van die clusters aan tot acht, met eigen varianten.
-- H12, H15 en de andere examenclusters hadden al acht vragen en blijven buiten deze migratie.
--
-- De controle verwacht ná deze migratie acht vragen per cluster. De
-- stappencontrole telt alleen de nieuwe opgaven.
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 4 topics, 4 clusters
--   • 16 vragen met elk 4 stappen (64 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('examentraining', $examentrainingsql$Examentraining$examentrainingsql$, 5, 16, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'examentraining' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('examen_inhoud_xas', $examentrainingsql$Inhoud om de x-as$examentrainingsql$, 5, 'toepassingen'),
  ('examen_inhoud_xas_grenzen', $examentrainingsql$Inhoud om de x-as, grenzen zelf$examentrainingsql$, 6, 'toepassingen'),
  ('examen_inhoud_yas', $examentrainingsql$Inhoud om de y-as$examentrainingsql$, 7, 'toepassingen'),
  ('examen_inhoud_yas_grenzen', $examentrainingsql$Inhoud om de y-as, grenzen zelf$examentrainingsql$, 8, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Grenzen gegeven$examentrainingsql$, 1),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Grenzen zelf vinden$examentrainingsql$, 1),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$y-waarden gegeven$examentrainingsql$, 1),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$y-waarden zelf zoeken$examentrainingsql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
  (site, topic_id, cluster_id, latex_body, answer, latex_answer, difficulty, order_index, is_ai_generated, answer_alternatives)
SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(13/3)pi$examentrainingsql$, $examentrainingsql$\dfrac{13}{3}\pi$examentrainingsql$, 2, 5, ARRAY[$examentrainingsql$(13/3)*pi$examentrainingsql$, $examentrainingsql$13pi/3$examentrainingsql$]::text[]),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(15/2)pi$examentrainingsql$, $examentrainingsql$\dfrac{15}{2}\pi$examentrainingsql$, 2, 6, ARRAY[$examentrainingsql$(15/2)*pi$examentrainingsql$, $examentrainingsql$15pi/2$examentrainingsql$]::text[]),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{2x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/4)(e^4-1)pi$examentrainingsql$, $examentrainingsql$\dfrac{1}{4}(e^{4} - 1)\pi$examentrainingsql$, 3, 7, ARRAY[$examentrainingsql$(1/4)*pi*(e^4-1)$examentrainingsql$, $examentrainingsql$pi*(e^4-1)/4$examentrainingsql$]::text[]),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(9/2+4ln(2))pi$examentrainingsql$, $examentrainingsql$\left(\dfrac{9}{2} + 4\ln(2)\right)\pi$examentrainingsql$, 3, 8, ARRAY[$examentrainingsql$pi*(9/2+4*ln(2))$examentrainingsql$, $examentrainingsql$(9/2)*pi+4*pi*ln(2)$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(81/10)pi$examentrainingsql$, $examentrainingsql$\dfrac{81}{10}\pi$examentrainingsql$, 3, 5, ARRAY[$examentrainingsql$(81/10)*pi$examentrainingsql$, $examentrainingsql$81pi/10$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/6)pi$examentrainingsql$, $examentrainingsql$\dfrac{1}{6}\pi$examentrainingsql$, 3, 6, ARRAY[$examentrainingsql$(1/6)*pi$examentrainingsql$, $examentrainingsql$pi/6$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \cos(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/4)pi^2$examentrainingsql$, $examentrainingsql$\dfrac{1}{4}\pi^{2}$examentrainingsql$, 3, 7, ARRAY[$examentrainingsql$pi^2/4$examentrainingsql$, $examentrainingsql$(pi^2)/4$examentrainingsql$]::text[]),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 4x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(512/15)pi$examentrainingsql$, $examentrainingsql$\dfrac{512}{15}\pi$examentrainingsql$, 3, 8, ARRAY[$examentrainingsql$(512/15)*pi$examentrainingsql$, $examentrainingsql$512pi/15$examentrainingsql$]::text[]),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y + 2$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(56/3)pi$examentrainingsql$, $examentrainingsql$\dfrac{56}{3}\pi$examentrainingsql$, 2, 5, ARRAY[$examentrainingsql$(56/3)*pi$examentrainingsql$, $examentrainingsql$56pi/3$examentrainingsql$]::text[]),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \sqrt{3y + 1}$, de $y$-as en de lijnen $y = 1$ en $y = 5$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$40pi$examentrainingsql$, $examentrainingsql$40\pi$examentrainingsql$, 2, 6, ARRAY[$examentrainingsql$40*pi$examentrainingsql$]::text[]),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{3y}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/6)(e^6-1)pi$examentrainingsql$, $examentrainingsql$\dfrac{1}{6}(e^{6} - 1)\pi$examentrainingsql$, 3, 7, ARRAY[$examentrainingsql$(1/6)*pi*(e^6-1)$examentrainingsql$, $examentrainingsql$pi*(e^6-1)/6$examentrainingsql$]::text[]),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 4}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(11/2+6ln(2))pi$examentrainingsql$, $examentrainingsql$\left(\dfrac{11}{2} + 6\ln(2)\right)\pi$examentrainingsql$, 3, 8, ARRAY[$examentrainingsql$pi*(11/2+6*ln(2))$examentrainingsql$, $examentrainingsql$(11/2)*pi+6*pi*ln(2)$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sqrt{4 - x}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(256/15)pi$examentrainingsql$, $examentrainingsql$\dfrac{256}{15}\pi$examentrainingsql$, 3, 5, ARRAY[$examentrainingsql$(256/15)*pi$examentrainingsql$, $examentrainingsql$256pi/15$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 3\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(9/2)pi^2$examentrainingsql$, $examentrainingsql$\dfrac{9}{2}\pi^{2}$examentrainingsql$, 3, 6, ARRAY[$examentrainingsql$(9/2)*pi^2$examentrainingsql$, $examentrainingsql$9pi^2/2$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 6 - 3x$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$8pi$examentrainingsql$, $examentrainingsql$8\pi$examentrainingsql$, 3, 7, ARRAY[$examentrainingsql$8*pi$examentrainingsql$]::text[]),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(2y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, $examentrainingsql$(1/8)pi^2$examentrainingsql$, $examentrainingsql$\dfrac{1}{8}\pi^{2}$examentrainingsql$, 3, 8, ARRAY[$examentrainingsql$pi^2/8$examentrainingsql$, $examentrainingsql$(pi^2)/8$examentrainingsql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. Op $[0, 1]$ is $f(x) \ge 1$, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{1} (2x + 1)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{1} (4x^{2} + 4x + 1)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{4}{3}x^{3} + 2x^{2} + x\right)$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \pi\left(\dfrac{4}{3} + 2 + 1\right) = \dfrac{13}{3}\pi$. De inhoud is $\dfrac{13}{3}\pi$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. Op $[0, 3]$ is $x + 1 > 0$, dus de grafiek ligt boven de $x$-as. Het kwadraat van de wortel is $x + 1$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{3} \left(\sqrt{x + 1}\right)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{3} (x + 1)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{2}x^{2} + x\right)$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(3) - F(0) = \pi\left(\dfrac{9}{2} + 3\right) = \dfrac{15}{2}\pi$. De inhoud is $\dfrac{15}{2}\pi$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{2x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. $e^{2x}$ is overal positief. Het kwadraat is $e^{4x}$. De kern van die macht is $4x$, met afgeleide $4$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{2x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{1} \left(e^{2x}\right)^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{1} e^{4x}\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{2x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi \cdot \dfrac{1}{4}e^{4x}$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{2x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \dfrac{1}{4}\pi e^{4} - \dfrac{1}{4}\pi = \dfrac{1}{4}(e^{4} - 1)\pi$. De inhoud is $\dfrac{1}{4}(e^{4} - 1)\pi$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. Op $[0, 1]$ zijn teller en noemer positief, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$. Schrijf de breuk eerst als een getal plus een rest.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$2x + 3 = 2\cdot(x + 1) + 1$, dus $f(x) = 2 + \dfrac{1}{x + 1}$. Dan $f(x)^{2} = 4 + \dfrac{4}{x + 1} + \dfrac{1}{(x + 1)^{2}}$. $I(L) = \pi \displaystyle\int_{0}^{1} \left(4 + \dfrac{4}{x + 1} + \dfrac{1}{(x + 1)^{2}}\right)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$De kern is $x + 1$, met afgeleide $1$. Een primitieve van de integrand is $F(x) = \pi\left(4x + 4\ln(x + 1) - \dfrac{1}{x + 1}\right)$.$examentrainingsql$),
  ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) = \pi\left(\dfrac{7}{2} + 4\ln(2)\right)$ en $F(0) = -\pi$. Het verschil is $\dfrac{7}{2} + 4\ln(2) - (-1) = \dfrac{9}{2} + 4\ln(2)$, maal $\pi$. De inhoud is $\left(\dfrac{9}{2} + 4\ln(2)\right)\pi$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafiek snijdt de $x$-as waar $3x - x^{2} = 0$, dus $x(3 - x) = 0$. De snijpunten zijn $x = 0$ en $x = 3$. Daartussen is $f(1) = 2$, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{3} (3x - x^{2})^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{3} (9x^{2} - 6x^{3} + x^{4})\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(3x^{3} - \dfrac{3}{2}x^{4} + \dfrac{1}{5}x^{5}\right)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(3) - F(0) = \pi\left(81 - \dfrac{243}{2} + \dfrac{243}{5}\right) = \pi\left(\dfrac{810}{10} - \dfrac{1215}{10} + \dfrac{486}{10}\right) = \dfrac{81}{10}\pi$. De inhoud is $\dfrac{81}{10}\pi$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafieken snijden elkaar waar $\sqrt{x} = x$. Kwadrateren geeft $x = x^{2}$, dus $x(x - 1) = 0$. Beide oplossingen kloppen: $x = 0$ en $x = 1$. Op dat stuk is $f\left(\dfrac{1}{4}\right) = \dfrac{1}{2}$ groter dan $g\left(\dfrac{1}{4}\right) = \dfrac{1}{4}$, dus $f$ ligt verder van de $x$-as. De inhoud is $\pi$ keer de integraal van het verschil van de kwadraten.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{1} \left(x - x^{2}\right)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{2}x^{2} - \dfrac{1}{3}x^{3}\right)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \pi\left(\dfrac{1}{2} - \dfrac{1}{3}\right) = \dfrac{1}{6}\pi$. De inhoud is $\dfrac{1}{6}\pi$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \cos(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. In het eerste kwadrant snijdt $\cos(x)$ de $x$-as in $x = \dfrac{\pi}{2}$. Samen met de $y$-as, waar $x = 0$, zijn dat de grenzen. Daartussen ligt de grafiek boven de $x$-as. De inhoud is $\pi$ keer de integraal van $\cos^{2}(x)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \cos(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$Gebruik $\cos^{2}(x) = \dfrac{1 + \cos(2x)}{2}$. $I(L) = \pi \displaystyle\int_{0}^{\frac{\pi}{2}} \dfrac{1 + \cos(2x)}{2}\,\mathrm{d}x$. De kern van de cosinus is $2x$, met afgeleide $2$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \cos(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{1}{2}x + \dfrac{1}{4}\sin(2x)\right)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \cos(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F\left(\dfrac{\pi}{2}\right) - F(0) = \pi \cdot \dfrac{\pi}{4} = \dfrac{1}{4}\pi^{2}$. De inhoud is $\dfrac{1}{4}\pi^{2}$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 4x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafiek snijdt de $x$-as waar $4x - x^{2} = 0$, dus $x(4 - x) = 0$. De snijpunten zijn $x = 0$ en $x = 4$. Daartussen is $f(2) = 4$, dus de grafiek ligt boven de $x$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 4x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{4} (4x - x^{2})^{2}\,\mathrm{d}x = \pi \displaystyle\int_{0}^{4} (16x^{2} - 8x^{3} + x^{4})\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 4x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(x) = \pi\left(\dfrac{16}{3}x^{3} - 2x^{4} + \dfrac{1}{5}x^{5}\right)$.$examentrainingsql$),
  ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 4x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(4) - F(0) = \pi\left(\dfrac{1024}{3} - 512 + \dfrac{1024}{5}\right) = \pi\left(\dfrac{5120}{15} - \dfrac{7680}{15} + \dfrac{3072}{15}\right) = \dfrac{512}{15}\pi$. De inhoud is $\dfrac{512}{15}\pi$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y + 2$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $0$ tot $2$. Op dat stuk is $f(y) \ge 2$, dus de grafiek ligt rechts van de $y$-as. De straal is $f(y)$. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y + 2$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{2} (y + 2)^{2}\,\mathrm{d}y$. Werk het kwadraat uit: dat is $\pi \displaystyle\int_{0}^{2} (y^{2} + 4y + 4)\,\mathrm{d}y$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y + 2$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(y) = \pi\left(\dfrac{1}{3}y^{3} + 2y^{2} + 4y\right)$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y + 2$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(2) - F(0) = \pi\left(\dfrac{8}{3} + 8 + 8\right) = \dfrac{56}{3}\pi$. De inhoud is $\dfrac{56}{3}\pi$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \sqrt{3y + 1}$, de $y$-as en de lijnen $y = 1$ en $y = 5$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $1$ tot $5$. Op dat stuk is $3y + 1 > 0$, dus de grafiek ligt rechts van de $y$-as. Het kwadraat van de wortel is $3y + 1$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \sqrt{3y + 1}$, de $y$-as en de lijnen $y = 1$ en $y = 5$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{1}^{5} \left(\sqrt{3y + 1}\right)^{2}\,\mathrm{d}y = \pi \displaystyle\int_{1}^{5} (3y + 1)\,\mathrm{d}y$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \sqrt{3y + 1}$, de $y$-as en de lijnen $y = 1$ en $y = 5$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi\left(\dfrac{3}{2}y^{2} + y\right)$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \sqrt{3y + 1}$, de $y$-as en de lijnen $y = 1$ en $y = 5$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(5) - F(1) = \pi\left(\dfrac{75}{2} + 5\right) - \pi\left(\dfrac{3}{2} + 1\right) = \dfrac{85}{2}\pi - \dfrac{5}{2}\pi = 40\pi$. De inhoud is $40\pi$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{3y}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $0$ tot $1$. $e^{3y}$ is overal positief, dus de grafiek ligt rechts van de $y$-as. Het kwadraat is $e^{6y}$. De kern van die macht is $6y$, met afgeleide $6$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{3y}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{1} \left(e^{3y}\right)^{2}\,\mathrm{d}y = \pi \displaystyle\int_{0}^{1} e^{6y}\,\mathrm{d}y$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{3y}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi \cdot \dfrac{1}{6}e^{6y}$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{3y}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) - F(0) = \dfrac{1}{6}\pi e^{6} - \dfrac{1}{6}\pi = \dfrac{1}{6}(e^{6} - 1)\pi$. De inhoud is $\dfrac{1}{6}(e^{6} - 1)\pi$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 4}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De $y$-waarden staan in de opgave: van $0$ tot $1$. Op dat stuk zijn teller en noemer positief, dus de grafiek ligt rechts van de $y$-as. De inhoud is $\pi$ keer de integraal van het kwadraat van $f$. Schrijf de breuk eerst als een getal plus een rest.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 4}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$y + 4 = 1\cdot(y + 1) + 3$, dus $f(y) = 1 + \dfrac{3}{y + 1}$. Het kwadraat is $1 + \dfrac{6}{y + 1} + \dfrac{9}{(y + 1)^{2}}$. $I(L)$ is $\pi$ keer de integraal daarvan van $0$ tot $1$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 4}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$De kern is $y + 1$, met afgeleide $1$. Een primitieve is $F(y) = \pi\left(y + 6\ln(y + 1) - \dfrac{9}{y + 1}\right)$.$examentrainingsql$),
  ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 4}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(1) = \pi\left(6\ln(2) - \dfrac{7}{2}\right)$ en $F(0) = -9\pi$. Het verschil is $6\ln(2) - \dfrac{7}{2} - (-9) = 6\ln(2) + \dfrac{11}{2}$, maal $\pi$. De inhoud is $\left(\dfrac{11}{2} + 6\ln(2)\right)\pi$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sqrt{4 - x}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafiek snijdt de $y$-as in $(0, 2)$. Hij snijdt de $x$-as waar $\sqrt{4 - x} = 0$, dus $x = 4$, en daar is $y = 0$. $V$ ligt dus tussen $y = 0$ en $y = 2$. Uit $y = \sqrt{4 - x}$ volgt $x = 4 - y^{2}$, met $x \ge 0$. De inhoud is $\pi$ keer de integraal van $x^{2}$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sqrt{4 - x}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{2} (4 - y^{2})^{2}\,\mathrm{d}y$. Dat is $\pi$ keer de integraal van $16 - 8y^{2} + y^{4}$ van $0$ tot $2$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sqrt{4 - x}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi\left(16y - \dfrac{8}{3}y^{3} + \dfrac{1}{5}y^{5}\right)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sqrt{4 - x}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(2) - F(0) = \pi\left(32 - \dfrac{64}{3} + \dfrac{32}{5}\right) = \pi\left(\dfrac{480}{15} - \dfrac{320}{15} + \dfrac{96}{15}\right) = \dfrac{256}{15}\pi$. De inhoud is $\dfrac{256}{15}\pi$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 3\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. $3\sin(y) = 0$ als $\sin(y) = 0$. De kleinste twee niet-negatieve oplossingen zijn $y = 0$ en $y = \pi$. Daartussen is $\sin(y) \ge 0$, dus de grafiek ligt rechts van de $y$-as of erop. De straal is $3\sin(y)$. De inhoud is $\pi$ keer de integraal van het kwadraat.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 3\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{\pi} (3\sin(y))^{2}\,\mathrm{d}y$. Dat is $\pi$ keer de integraal van $9\sin^{2}(y)$ van $0$ tot $\pi$. Gebruik $\sin^{2}(y) = \dfrac{1 - \cos(2y)}{2}$, dus $9\sin^{2}(y) = \dfrac{9}{2} - \dfrac{9}{2}\cos(2y)$. De kern van de cosinus is $2y$, met afgeleide $2$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 3\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi\left(\dfrac{9}{2}y - \dfrac{9}{4}\sin(2y)\right)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 3\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(\pi) = \dfrac{9}{2}\pi^{2}$ en $F(0) = 0$. De inhoud is $\dfrac{9}{2}\pi^{2}$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 6 - 3x$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De grafiek snijdt de $y$-as in $(0, 6)$. Hij snijdt de $x$-as waar $6 - 3x = 0$, dus $x = 2$, en daar is $y = 0$. $V$ ligt dus tussen $y = 0$ en $y = 6$. Uit $y = 6 - 3x$ volgt $x = \dfrac{6 - y}{3}$. De inhoud is $\pi$ keer de integraal van $x^{2}$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 6 - 3x$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$$I(L) = \pi \displaystyle\int_{0}^{6} \left(\dfrac{6 - y}{3}\right)^{2}\,\mathrm{d}y$. Dat is $\pi$ keer de integraal van $\left(2 - \dfrac{1}{3}y\right)^{2}$ van $0$ tot $6$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 6 - 3x$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi\left(4y - \dfrac{2}{3}y^{2} + \dfrac{1}{27}y^{3}\right)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 6 - 3x$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F(6) - F(0) = \pi\left(24 - 24 + 8\right) = 8\pi$. De inhoud is $8\pi$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(2y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen deel 1 en deel 2 van de driedeling: eerst vertaal je het verhaal naar een integraal, daarna reken je die integraal exact uit. De onderste $y$-waarde is $0$. $\cos(2y) = 0$ bij $2y = \dfrac{\pi}{2}$, dus $y = \dfrac{\pi}{4}$. Dat is de kleinste positieve oplossing. Daartussen is $\cos(2y) > 0$, dus de grafiek ligt rechts van de $y$-as. De straal is $\cos(2y)$. De inhoud is $\pi$ keer de integraal van $\cos^{2}(2y)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(2y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 1, $examentrainingsql$Gebruik $\cos^{2}(2y) = \dfrac{1 + \cos(4y)}{2}$. $I(L)$ is $\pi$ keer de integraal daarvan van $0$ tot $\dfrac{\pi}{4}$. De kern van de cosinus is $4y$, met afgeleide $4$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(2y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van de integrand is $F(y) = \pi\left(\dfrac{1}{2}y + \dfrac{1}{8}\sin(4y)\right)$.$examentrainingsql$),
  ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(2y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$, 3, $examentrainingsql$$F\left(\dfrac{\pi}{4}\right) - F(0) = \pi \cdot \dfrac{\pi}{8} = \dfrac{1}{8}\pi^{2}$. De inhoud is $\dfrac{1}{8}\pi^{2}$.$examentrainingsql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_xas' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_xas' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster examen_inhoud_xas hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_xas_grenzen' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_xas_grenzen' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster examen_inhoud_xas_grenzen hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_yas' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_yas' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster examen_inhoud_yas hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_inhoud_yas_grenzen' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_inhoud_yas_grenzen' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster examen_inhoud_yas_grenzen hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topic_clusters_new cl ON cl.id = vr.cluster_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  JOIN (VALUES
    ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 2x + 1$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \sqrt{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = e^{2x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_xas', 'examen_inhoud_xas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = \dfrac{2x + 3}{x + 1}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 3x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafieken van $f(x) = \sqrt{x}$ en $g(x) = x$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \cos(x)$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_xas_grenzen', 'examen_inhoud_xas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(x) = 4x - x^{2}$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = y + 2$, de $y$-as en de lijnen $y = 0$ en $y = 2$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \sqrt{3y + 1}$, de $y$-as en de lijnen $y = 1$ en $y = 5$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = e^{3y}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas', 'examen_inhoud_yas', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \dfrac{y + 4}{y + 1}$, de $y$-as en de lijnen $y = 0$ en $y = 1$. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = \sqrt{4 - x}$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = 3\sin(y)$ en de $y$-as, tussen de kleinste twee niet-negatieve $y$-waarden waar de grafiek de $y$-as snijdt. Zoek die $y$-waarden zelf. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door de grafiek van $f(x) = 6 - 3x$ en de coördinaatassen. Zoek zelf de $y$-waarden waartussen $V$ ligt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$),
    ('examen_inhoud_yas_grenzen', 'examen_inhoud_yas_grenzen', $examentrainingsql$Het vlakdeel $V$ wordt ingesloten door de grafiek van $f(y) = \cos(2y)$, de $y$-as en de lijn $y = 0$. De onderste $y$-waarde is $0$. Zoek zelf de kleinste positieve $y$-waarde waar de grafiek de $y$-as snijdt. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$examentrainingsql$)
  ) AS v(topic_slug, cluster_slug, latex_body)
    ON t.slug = v.topic_slug AND t.site = 'integralen'
   AND cl.slug = v.cluster_slug AND cl.topic_id = t.id
   AND vr.latex_body = v.latex_body;
  IF n <> 64 THEN RAISE EXCEPTION 'Deze vragen horen samen 64 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
